import UIKit
import os.log

private let iconLog = Logger(subsystem: "dev.jdpedrie.psmith", category: "AppIcon")

/// Keeps the home-screen icon in the active theme's colors. Each theme
/// other than System ships an alternate icon (`AppIcon-<Theme>` in the
/// asset catalog, generated by scripts/recolor-app-icon.swift); System
/// uses the primary icon.
///
/// iOS shows its own "You have changed the icon" alert on every switch
/// and offers no way to suppress it, so this only calls when the icon
/// actually differs.
enum AppIconSync {
    /// The alternate icon for a theme, nil for the primary icon.
    static func iconName(forThemeID id: String) -> String? {
        switch id {
        case "sage": return "AppIcon-Sage"
        case "clay": return "AppIcon-Clay"
        case "slate": return "AppIcon-Slate"
        case "aubergine": return "AppIcon-Aubergine"
        case "nordic": return "AppIcon-Nordic"
        default: return nil
        }
    }

    @MainActor
    static func apply(themeID: String) {
        let app = UIApplication.shared
        guard app.supportsAlternateIcons else { return }
        let wanted = iconName(forThemeID: themeID)
        guard app.alternateIconName != wanted else { return }
        app.setAlternateIconName(wanted) { error in
            // Fails when the app isn't frontmost; the next launch or
            // theme change retries.
            if let error {
                iconLog.error("icon switch to \(wanted ?? "primary", privacy: .public) failed: \(error.localizedDescription, privacy: .public)")
            }
        }
    }
}
